const e={"f-card-c7a-teach":{kind:"lesson",src:"card:c7a#teach",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"The snowball",body:"Interest lands on your money. Next time, it lands on your money plus the interest. That's compounding — boring for a year, then not.",route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",card:"c7a",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-teach",bands:["sprout","builder"]},"f-card-c7a-eg":{kind:"example",src:"card:c7a#eg",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"The snowball",body:"100 growing 10% a year: 110, then 121, then 133. The steps get bigger on their own.",route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-eg",bands:["sprout","builder"]},"f-lesson-c7a-beat0":{kind:"line",src:"lesson:c7a#beat0",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"The snowball",body:"Interest lands on your money. You know that part.",route:"#/atlas/c7a",cta:"Watch the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-lesson-c7a-beat0",bands:["sprout","builder"]},"f-lesson-c7a-beat1":{kind:"line",src:"lesson:c7a#beat1",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"The snowball",body:"Here is the part that changes everything: next time, it lands on your money PLUS the interest.",route:"#/atlas/c7a",cta:"Watch the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-lesson-c7a-beat1",bands:["sprout","builder"]},"f-lesson-c7a-beat2":{kind:"line",src:"lesson:c7a#beat2",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"The snowball",body:"One hundred, growing ten percent a year. One hundred and ten. Then one hundred and twenty-one. Then one hundred and thirty-three.",route:"#/atlas/c7a",cta:"Watch the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-lesson-c7a-beat2",bands:["sprout","builder"]},"f-lesson-c7a-beat3":{kind:"line",src:"lesson:c7a#beat3",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"The snowball",body:"The steps get bigger while you do nothing at all. That is compounding.",route:"#/atlas/c7a",cta:"Watch the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-lesson-c7a-beat3",bands:["sprout","builder"]},"f-lesson-c7a-beat4":{kind:"line",src:"lesson:c7a#beat4",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"The snowball",body:"It is boring for a year. And then it is not boring at all.",route:"#/atlas/c7a",cta:"Watch the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-lesson-c7a-beat4",bands:["sprout","builder"]},"f-card-c7a-q0":{kind:"question",src:"card:c7a#q0",level:7,topics:["card:c7a","ch:c7","who:pip"],key:"c7a#0",title:"The snowball",play:{q:"Why does the second year add more than the first?",opts:["There is more money for the rate to land on","The rate went up","The bank felt generous","Prices rose"],after:"Growth stacks on growth. Time does the work, so starting early beats starting big."},route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-q0",bands:["sprout","builder"]},"f-card-c7a-q1":{kind:"question",src:"card:c7a#q1",level:7,topics:["card:c7a","ch:c7","who:pip"],key:"c7a#1",title:"The snowball",play:{q:"100 grows 10% a year. Why is year three’s step bigger than year one’s?",opts:["Interest now lands on interest too","Banks raise rates yearly","It is not — steps are equal","Prices rose meanwhile"],after:"110, 121, 133 — each step lands on everything before it. That is compounding."},route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-q1",bands:["sprout","builder"]},"f-card-c7a-q2":{kind:"question",src:"card:c7a#q2",level:7,topics:["card:c7a","ch:c7","who:pip"],key:"c7a#2",title:"The snowball",play:{q:"What do YOU have to do while compounding works?",opts:["Nothing at all","Move banks yearly","Check it every day","Add money every week"],after:"The steps get bigger while you do nothing. Boring for a year — then not boring at all."},route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-q2",bands:["sprout","builder"]},"f-card-c7a-why0":{kind:"why",src:"card:c7a#why0",level:7,topics:["card:c7a","ch:c7","who:pip"],card:"c7a",title:"The snowball",body:"Growth stacks on growth. Time does the work, so starting early beats starting big.",route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-why0",bands:["sprout","builder"]},"f-card-c7a-why1":{kind:"why",src:"card:c7a#why1",level:7,topics:["card:c7a","ch:c7","who:pip"],card:"c7a",title:"The snowball",body:"110, 121, 133 — each step lands on everything before it. That is compounding.",route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-why1",bands:["sprout","builder"]},"f-card-c7a-why2":{kind:"why",src:"card:c7a#why2",level:7,topics:["card:c7a","ch:c7","who:pip"],card:"c7a",title:"The snowball",body:"The steps get bigger while you do nothing. Boring for a year — then not boring at all.",route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7a-why2",bands:["sprout","builder"]},"f-item-c7a":{kind:"yourturn",src:"item:c7a",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"Your turn",body:`The snowball, one more step
A tenth of a number is that number split into ten equal parts. Add one part on.`,route:"#/atlas/c7a",cta:"Have a go",maths:"M11",source:"Chapter 7 · Money that grows · The snowball · with Pip",id:"f-item-c7a",bands:["sprout","builder"]},"f-tryit-c7a":{kind:"tryit",src:"tryit:c7a",level:7,topics:["card:c7a","ch:c7","who:pip"],title:"Try it",body:"Watch it snowball",route:"#/atlas/c7a",cta:"Change the numbers",maths:"M11",source:"Chapter 7 · Money that grows · The snowball · with Pip",id:"f-tryit-c7a",bands:["sprout","builder"]},"f-card-c7b-teach":{kind:"lesson",src:"card:c7b#teach",level:7,topics:["card:c7b","ch:c7","who:bo"],title:"Risk and return",body:"Things that might grow a lot can also fall a lot — it's the same sentence. Safe things grow slowly. Big returns with no risk? Someone's confused or lying.",route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",card:"c7b",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-teach",bands:["sprout","builder"]},"f-card-c7b-eg":{kind:"example",src:"card:c7b#eg",level:7,topics:["card:c7b","ch:c7","who:bo"],title:"Risk and return",body:"Bo says it'll go up. Bea says down. Neither knows, and both are sure.",route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-eg",bands:["sprout","builder"]},"f-lesson-c7b-beat1":{kind:"line",src:"lesson:c7b#beat1",level:7,topics:["card:c7b","ch:c7","who:bo"],title:"Risk and return",body:"Hear it properly: that is one sentence, not two. The same sentence.",route:"#/atlas/c7b",cta:"Watch the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-lesson-c7b-beat1",bands:["sprout","builder"]},"f-lesson-c7b-beat2":{kind:"line",src:"lesson:c7b#beat2",level:7,topics:["card:c7b","ch:c7","who:bo"],title:"Risk and return",body:"Safe things grow slowly. That is their half of the deal.",route:"#/atlas/c7b",cta:"Watch the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-lesson-c7b-beat2",bands:["sprout","builder"]},"f-lesson-c7b-beat4":{kind:"line",src:"lesson:c7b#beat4",level:7,topics:["card:c7b","ch:c7","who:bo"],title:"Risk and return",body:"So when somebody promises big returns with no risk, they are either confused or lying. There is no third kind.",route:"#/atlas/c7b",cta:"Watch the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-lesson-c7b-beat4",bands:["sprout","builder"]},"f-card-c7b-q0":{kind:"question",src:"card:c7b#q0",level:7,topics:["card:c7b","ch:c7","who:bo"],key:"c7b#0",title:"Risk and return",play:{q:'Somebody offers a "guaranteed" way to double your money in a month. What is the safe read?',opts:["Guaranteed and doubling do not belong in the same sentence","Take it quickly before it goes","Ask them to do it twice","Only put in half"],after:"High return with no risk is the oldest scam there is."},route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-q0",bands:["sprout","builder"]},"f-card-c7b-q1":{kind:"question",src:"card:c7b#q1",level:7,topics:["card:c7b","ch:c7","who:bo"],key:"c7b#1",title:"Risk and return",play:{q:'"Might grow a lot" and "might fall a lot" are…',opts:["The same sentence about one thing","Bo’s view versus Bea’s","Two different investments","A safe one and a risky one"],after:"One sentence, not two. Big possible up IS big possible down."},route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-q1",bands:["sprout","builder"]},"f-card-c7b-q2":{kind:"question",src:"card:c7b#q2",level:7,topics:["card:c7b","ch:c7","who:bo"],key:"c7b#2",title:"Risk and return",play:{q:"Someone promises big returns with NO risk. The card says they are…",opts:["Confused or lying","A bank in disguise","A very lucky investor","Probably a genius"],after:"There is no third kind. Safe grows slowly; anything promising otherwise is broken somewhere."},route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-q2",bands:["sprout","builder"]},"f-card-c7b-why0":{kind:"why",src:"card:c7b#why0",level:7,topics:["card:c7b","ch:c7","who:bo"],card:"c7b",title:"Risk and return",body:"High return with no risk is the oldest scam there is.",route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-why0",bands:["sprout","builder"]},"f-card-c7b-why1":{kind:"why",src:"card:c7b#why1",level:7,topics:["card:c7b","ch:c7","who:bo"],card:"c7b",title:"Risk and return",body:"One sentence, not two. Big possible up IS big possible down.",route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-why1",bands:["sprout","builder"]},"f-card-c7b-why2":{kind:"why",src:"card:c7b#why2",level:7,topics:["card:c7b","ch:c7","who:bo"],card:"c7b",title:"Risk and return",body:"There is no third kind. Safe grows slowly; anything promising otherwise is broken somewhere.",route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7b-why2",bands:["sprout","builder"]},"f-item-c7b":{kind:"yourturn",src:"item:c7b",level:7,topics:["card:c7b","ch:c7","who:bo"],title:"Your turn",body:`Makes sense, or broken?
A big possible up comes with a big possible down. Anything promising one without the other is broken.`,route:"#/atlas/c7b",cta:"Have a go",maths:"M10",source:"Chapter 7 · Money that grows · Risk and return · with Bo",id:"f-item-c7b",bands:["sprout","builder"]},"f-card-c7i-teach":{kind:"lesson",src:"card:c7i#teach",level:7,topics:["card:c7i","ch:c7","who:bea"],title:"What a share is",body:"A business can be split into many equal pieces called shares. Own one and you own a small slice: a slice of its profits, and a slice of its bad years too. Its price moves with what people think it will earn.",route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",card:"c7i",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-teach",bands:["sprout","builder"]},"f-card-c7i-eg":{kind:"example",src:"card:c7i#eg",level:7,topics:["card:c7i","ch:c7","who:bea"],title:"What a share is",body:"A bakery split into 100 shares makes 300 profit and pays it all out. Each share gets 300 ÷ 100 = 3.",route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-eg",bands:["sprout","builder"]},"f-card-c7i-q0":{kind:"question",src:"card:c7i#q0",level:7,topics:["card:c7i","ch:c7","who:bea"],key:"c7i#0",title:"What a share is",play:{q:"You own one share of a bakery. What do you actually own?",opts:["A small slice of the whole business","A loan you made to the baker","The right to run the shop","A loaf of bread every week"],after:"A share is part-ownership. Good years and bad years both land on you, in a small slice."},route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-q0",bands:["sprout","builder"]},"f-card-c7i-q1":{kind:"question",src:"card:c7i#q1",level:7,topics:["card:c7i","ch:c7","who:bea"],key:"c7i#1",title:"What a share is",play:{q:"Why does the price of a share go up and down?",opts:["People change what they think it will earn","Bo and Bea vote on it","It is fixed when the shop opens","The bank sets it each morning"],after:"A price is what buyers will pay today, and that moves with every guess about tomorrow."},route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-q1",bands:["sprout","builder"]},"f-card-c7i-q2":{kind:"question",src:"card:c7i#q2",level:7,topics:["card:c7i","ch:c7","who:bea"],key:"c7i#2",title:"What a share is",play:{q:"The bakery has a terrible year. What happens to someone who owns a share?",opts:["They share in the bad year too","Nothing, shares are safe","Their share turns into cash","The baker must pay them back"],after:"Owning a slice means owning the bad years as well as the good. That is the risk in risk and return."},route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-q2",bands:["sprout","builder"]},"f-card-c7i-why0":{kind:"why",src:"card:c7i#why0",level:7,topics:["card:c7i","ch:c7","who:bea"],card:"c7i",title:"What a share is",body:"A share is part-ownership. Good years and bad years both land on you, in a small slice.",route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-why0",bands:["sprout","builder"]},"f-card-c7i-why1":{kind:"why",src:"card:c7i#why1",level:7,topics:["card:c7i","ch:c7","who:bea"],card:"c7i",title:"What a share is",body:"A price is what buyers will pay today, and that moves with every guess about tomorrow.",route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-why1",bands:["sprout","builder"]},"f-card-c7i-why2":{kind:"why",src:"card:c7i#why2",level:7,topics:["card:c7i","ch:c7","who:bea"],card:"c7i",title:"What a share is",body:"Owning a slice means owning the bad years as well as the good. That is the risk in risk and return.",route:"#/atlas/c7i",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7i-why2",bands:["sprout","builder"]},"f-item-c7i":{kind:"yourturn",src:"item:c7i",level:7,topics:["card:c7i","ch:c7","who:bea"],title:"Your turn",body:`Your slice of the profit
Find what one share gets first, then count your shares.`,route:"#/atlas/c7i",cta:"Have a go",maths:"M12",source:"Chapter 7 · Money that grows · What a share is · with Bea",id:"f-item-c7i",bands:["sprout","builder"]},"f-card-c7c-teach":{kind:"lesson",src:"card:c7c#teach",level:7,topics:["card:c7c","ch:c7","who:bea"],title:"Never just one",body:"Own a slice of many things and no single bad news can wreck you. Own one thing and your week depends on someone else's Tuesday.",route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",card:"c7c",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-teach",bands:["sprout","builder"]},"f-card-c7c-eg":{kind:"example",src:"card:c7c#eg",level:7,topics:["card:c7c","ch:c7","who:bea"],title:"Never just one",body:"A basket of the whole market is dull — and dull wins more often than exciting.",route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-eg",bands:["sprout","builder"]},"f-lesson-c7c-beat4":{kind:"line",src:"lesson:c7c#beat4",level:7,topics:["card:c7c","ch:c7","who:bea"],title:"Never just one",body:"Spreading out is the only free thing in this entire subject. Take it.",route:"#/atlas/c7c",cta:"Watch the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-lesson-c7c-beat4",bands:["sprout","builder"]},"f-card-c7c-q0":{kind:"question",src:"card:c7c#q0",level:7,topics:["card:c7c","ch:c7","who:bea"],key:"c7c#0",title:"Never just one",play:{q:"Why spread money across many things instead of the one you like best?",opts:["One piece of bad news can no longer sink everything","It costs less","It grows faster","The best one is hard to find"],after:"Spreading out doesn't raise your best score. It raises your worst — and the worst is what ends games."},route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-q0",bands:["sprout","builder"]},"f-card-c7c-q1":{kind:"question",src:"card:c7c#q1",level:7,topics:["card:c7c","ch:c7","who:bea"],key:"c7c#1",title:"Never just one",play:{q:"Owning shares in one single company means…",opts:["Your week rides on their Tuesday","You control the company","Bigger guaranteed returns","Lower fees than baskets"],after:"One piece of bad news, and it is your news. A slice of many things shrugs it off."},route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-q1",bands:["sprout","builder"]},"f-card-c7c-q2":{kind:"question",src:"card:c7c#q2",level:7,topics:["card:c7c","ch:c7","who:bea"],key:"c7c#2",title:"Never just one",play:{q:'Why does the card call spreading out "the only free thing in this subject"?',opts:["Less wreck-risk without less return","Baskets charge no fees","Dull things cost nothing","Banks give baskets away"],after:"Diversifying cuts the chance of ruin without costing you the growth. Nothing else in finance is free."},route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-q2",bands:["sprout","builder"]},"f-card-c7c-why0":{kind:"why",src:"card:c7c#why0",level:7,topics:["card:c7c","ch:c7","who:bea"],card:"c7c",title:"Never just one",body:"Spreading out doesn't raise your best score. It raises your worst — and the worst is what ends games.",route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-why0",bands:["sprout","builder"]},"f-card-c7c-why1":{kind:"why",src:"card:c7c#why1",level:7,topics:["card:c7c","ch:c7","who:bea"],card:"c7c",title:"Never just one",body:"One piece of bad news, and it is your news. A slice of many things shrugs it off.",route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-why1",bands:["sprout","builder"]},"f-card-c7c-why2":{kind:"why",src:"card:c7c#why2",level:7,topics:["card:c7c","ch:c7","who:bea"],card:"c7c",title:"Never just one",body:"Diversifying cuts the chance of ruin without costing you the growth. Nothing else in finance is free.",route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7c-why2",bands:["sprout","builder"]},"f-item-c7c":{kind:"yourturn",src:"item:c7c",level:7,topics:["card:c7c","ch:c7","who:bea"],title:"Your turn",body:`One basket, or many?
If one thing has a bad week, which basket still has the rest?`,route:"#/atlas/c7c",cta:"Have a go",maths:"M8",source:"Chapter 7 · Money that grows · Never just one · with Bea",id:"f-item-c7c",bands:["sprout","builder"]},"f-card-c7d-teach":{kind:"lesson",src:"card:c7d#teach",level:7,topics:["card:c7d","ch:c7","who:nana"],title:"Time is the ingredient",body:"Money you need next month must be safe, even if it barely grows. Money you won't touch for ten years has time to ride out bad weather.",route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",card:"c7d",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-teach",bands:["sprout","builder"]},"f-card-c7d-eg":{kind:"example",src:"card:c7d#eg",level:7,topics:["card:c7d","ch:c7","who:nana"],title:"Time is the ingredient",body:"Bus fare and a far-off fund are different money, and they live in different places.",route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-eg",bands:["sprout","builder"]},"f-lesson-c7d-beat0":{kind:"line",src:"lesson:c7d#beat0",level:7,topics:["card:c7d","ch:c7","who:nana"],title:"Time is the ingredient",body:"Where money should live depends on one question: when will you need it back?",route:"#/atlas/c7d",cta:"Watch the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-lesson-c7d-beat0",bands:["sprout","builder"]},"f-lesson-c7d-beat1":{kind:"line",src:"lesson:c7d#beat1",level:7,topics:["card:c7d","ch:c7","who:nana"],title:"Time is the ingredient",body:"Money you need next month must sit somewhere safe — even if it grows by almost nothing.",route:"#/atlas/c7d",cta:"Watch the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-lesson-c7d-beat1",bands:["sprout","builder"]},"f-lesson-c7d-beat2":{kind:"line",src:"lesson:c7d#beat2",level:7,topics:["card:c7d","ch:c7","who:nana"],title:"Time is the ingredient",body:"Money you will not touch for ten years can sit through bad weather. It has time to come back.",route:"#/atlas/c7d",cta:"Watch the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-lesson-c7d-beat2",bands:["sprout","builder"]},"f-lesson-c7d-beat3":{kind:"line",src:"lesson:c7d#beat3",level:7,topics:["card:c7d","ch:c7","who:nana"],title:"Time is the ingredient",body:"The bus fare and the retirement fund are not the same money.",route:"#/atlas/c7d",cta:"Watch the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-lesson-c7d-beat3",bands:["sprout","builder"]},"f-lesson-c7d-beat4":{kind:"line",src:"lesson:c7d#beat4",level:7,topics:["card:c7d","ch:c7","who:nana"],title:"Time is the ingredient",body:"And they must not live in the same place.",route:"#/atlas/c7d",cta:"Watch the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-lesson-c7d-beat4",bands:["sprout","builder"]},"f-card-c7d-q0":{kind:"question",src:"card:c7d#q0",level:7,topics:["card:c7d","ch:c7","who:nana"],key:"c7d#0",title:"Time is the ingredient",play:{q:"You need the money in three weeks. Where does it belong?",opts:["Somewhere safe and boring","Whatever grew most last year","Split across four companies","The one your friend likes"],after:"When you need it decides where it goes — before asking what grows fastest."},route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-q0",bands:["sprout","builder"]},"f-card-c7d-q1":{kind:"question",src:"card:c7d#q1",level:7,topics:["card:c7d","ch:c7","who:nana"],key:"c7d#1",title:"Time is the ingredient",play:{q:"Money you need next month belongs…",opts:["Somewhere safe, even if it barely grows","Wherever it grows fastest","With the ten-year money","Split across many shares"],after:"Next-month money cannot sit through a storm. Safety is its job; growth is not."},route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-q1",bands:["sprout","builder"]},"f-card-c7d-q2":{kind:"question",src:"card:c7d#q2",level:7,topics:["card:c7d","ch:c7","who:nana"],key:"c7d#2",title:"Money that grows",play:{q:"Why can ten-year money ride out a bad year?",opts:["It has time to come back","It cannot — sell at once","Banks protect old money","Bad years refund later"],after:"Time is the ingredient: what falls has years to recover before you need it."},route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-q2",bands:["sprout","builder"]},"f-card-c7d-why0":{kind:"why",src:"card:c7d#why0",level:7,topics:["card:c7d","ch:c7","who:nana"],card:"c7d",title:"Time is the ingredient",body:"When you need it decides where it goes — before asking what grows fastest.",route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-why0",bands:["sprout","builder"]},"f-card-c7d-why1":{kind:"why",src:"card:c7d#why1",level:7,topics:["card:c7d","ch:c7","who:nana"],card:"c7d",title:"Time is the ingredient",body:"Next-month money cannot sit through a storm. Safety is its job; growth is not.",route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-why1",bands:["sprout","builder"]},"f-card-c7d-why2":{kind:"why",src:"card:c7d#why2",level:7,topics:["card:c7d","ch:c7","who:nana"],card:"c7d",title:"Time is the ingredient",body:"Time is the ingredient: what falls has years to recover before you need it.",route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7d-why2",bands:["sprout","builder"]},"f-card-c7j-teach":{kind:"lesson",src:"card:c7j#teach",level:7,topics:["card:c7j","ch:c7","who:nana"],title:"Little and often, started early",body:"A small amount put away every week becomes a big amount, given time. And starting sooner beats putting in more later: the first coins have the longest to grow.",route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",card:"c7j",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-teach",bands:["sprout","builder"]},"f-card-c7j-eg":{kind:"example",src:"card:c7j#eg",level:7,topics:["card:c7j","ch:c7","who:nana"],title:"Little and often, started early",body:"Asha puts away 20 a month from January. Ravi starts in July. By December, before any growth, Asha has put in 240 and Ravi 120.",route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-eg",bands:["sprout","builder"]},"f-card-c7j-q0":{kind:"question",src:"card:c7j#q0",level:7,topics:["card:c7j","ch:c7","who:nana"],key:"c7j#0",title:"Little and often, started early",play:{q:"Asha and Ravi both put away 20 a month. Asha starts a year earlier. Who ends up with more?",opts:["Asha: more months in, and longer to grow","Whoever picks the luckier month","Ravi, because he waited","The same, as they save the same"],after:"Same amount each month, more months of it, and every early coin had longer to grow."},route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-q0",bands:["sprout","builder"]},"f-card-c7j-q1":{kind:"question",src:"card:c7j#q1",level:7,topics:["card:c7j","ch:c7","who:nana"],key:"c7j#1",title:"Little and often, started early",play:{q:"Why can a small amount, put away often, become a lot?",opts:["It adds up, and the growth grows too","Small amounts are never charged","Banks give small savers extra","It cannot, only big amounts grow"],after:"Many small amounts make a big one, and the snowball works on all of it."},route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-q1",bands:["sprout","builder"]},"f-card-c7j-q2":{kind:"question",src:"card:c7j#q2",level:7,topics:["card:c7j","ch:c7","who:nana"],key:"c7j#2",title:"Little and often, started early",play:{q:"Two friends put away the same amount each week. One starts this year, one in three years. Before any growth, how far ahead is the early one?",opts:["By three years of payments","By just one payment","By nothing, they pay the same","Only ahead if the rate is high"],after:"Same amount, three more years of it — and once growth is added, those early years count for even more."},route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-q2",bands:["sprout","builder"]},"f-card-c7j-why0":{kind:"why",src:"card:c7j#why0",level:7,topics:["card:c7j","ch:c7","who:nana"],card:"c7j",title:"Little and often, started early",body:"Same amount each month, more months of it, and every early coin had longer to grow.",route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-why0",bands:["sprout","builder"]},"f-card-c7j-why1":{kind:"why",src:"card:c7j#why1",level:7,topics:["card:c7j","ch:c7","who:nana"],card:"c7j",title:"Little and often, started early",body:"Many small amounts make a big one, and the snowball works on all of it.",route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-why1",bands:["sprout","builder"]},"f-card-c7j-why2":{kind:"why",src:"card:c7j#why2",level:7,topics:["card:c7j","ch:c7","who:nana"],card:"c7j",title:"Little and often, started early",body:"Same amount, three more years of it — and once growth is added, those early years count for even more.",route:"#/atlas/c7j",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7j-why2",bands:["sprout","builder"]},"f-item-c7j":{kind:"yourturn",src:"item:c7j",level:7,topics:["card:c7j","ch:c7","who:nana"],title:"Your turn",body:`Starting sooner
Work out what each one put in — months times the amount — then find the gap.`,route:"#/atlas/c7j",cta:"Have a go",maths:"M12",source:"Chapter 7 · Money that grows · Little and often, started early · with Nana Bizz",id:"f-item-c7j",bands:["sprout","builder"]},"f-card-c7e-teach":{kind:"lesson",src:"card:c7e#teach",level:7,topics:["card:c7e","ch:c7","who:bea"],title:"Fees grow too",body:"A small fee taken every year does not just cost the fee. It also costs everything that fee would have grown into. Fees compound, the same as growth does.",route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",card:"c7e",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-teach",bands:["sprout","builder"]},"f-card-c7e-eg":{kind:"example",src:"card:c7e#eg",level:7,topics:["card:c7e","ch:c7","who:bea"],title:"Fees grow too",body:"Two baskets grow the same. One takes a small fee each year. Years later it is behind by more than all the fees added up.",route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-eg",bands:["sprout","builder"]},"f-card-c7e-q0":{kind:"question",src:"card:c7e#q0",level:7,topics:["card:c7e","ch:c7","who:bea"],key:"c7e#0",title:"Fees grow too",play:{q:"Two funds grow alike, but one takes a small yearly fee. After twenty years, how far behind is it?",opts:["By more than the fees it charged","By less, because fees shrink","Not at all — fees are tiny","By exactly the fees it charged"],after:"Each fee also takes away the growth it would have earned, year after year."},route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-q0",bands:["sprout","builder"]},"f-card-c7e-q1":{kind:"question",src:"card:c7e#q1",level:7,topics:["card:c7e","ch:c7","who:bea"],key:"c7e#1",title:"Fees grow too",play:{q:"Why is a small yearly fee worth checking before you choose where money grows?",opts:["It quietly takes growth every year","Fees only matter for big amounts","It is taken once and forgotten","It is always paid back later"],after:"Small and every year is exactly the shape that adds up."},route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-q1",bands:["sprout","builder"]},"f-card-c7e-q2":{kind:"question",src:"card:c7e#q2",level:7,topics:["card:c7e","ch:c7","who:bea"],key:"c7e#2",title:"Fees grow too",play:{q:"Two baskets grow at the same speed. Which ends up bigger?",opts:["The one without the fee","Whichever started second","The one with the fee","They end the same"],after:"Same growth, less taken out — the one without the fee stays ahead, and the gap widens."},route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-q2",bands:["sprout","builder"]},"f-card-c7e-why0":{kind:"why",src:"card:c7e#why0",level:7,topics:["card:c7e","ch:c7","who:bea"],card:"c7e",title:"Fees grow too",body:"Each fee also takes away the growth it would have earned, year after year.",route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-why0",bands:["sprout","builder"]},"f-card-c7e-why1":{kind:"why",src:"card:c7e#why1",level:7,topics:["card:c7e","ch:c7","who:bea"],card:"c7e",title:"Fees grow too",body:"Small and every year is exactly the shape that adds up.",route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-why1",bands:["sprout","builder"]},"f-card-c7e-why2":{kind:"why",src:"card:c7e#why2",level:7,topics:["card:c7e","ch:c7","who:bea"],card:"c7e",title:"Fees grow too",body:"Same growth, less taken out — the one without the fee stays ahead, and the gap widens.",route:"#/atlas/c7e",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bea",id:"f-card-c7e-why2",bands:["sprout","builder"]},"f-card-c7f-teach":{kind:"lesson",src:"card:c7f#teach",level:7,topics:["card:c7f","ch:c7","who:bo"],title:"The doubling trick",body:"A quick way to guess how long money takes to double: divide 72 by the yearly growth. It is a rough guide, not a promise — but it makes slow growth easy to picture.",route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",card:"c7f",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-teach",bands:["sprout","builder"]},"f-card-c7f-eg":{kind:"example",src:"card:c7f#eg",level:7,topics:["card:c7f","ch:c7","who:bo"],title:"The doubling trick",body:"Growing 6 a year in every 100: 72 ÷ 6 = 12. About twelve years to double.",route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-eg",bands:["sprout","builder"]},"f-card-c7f-q0":{kind:"question",src:"card:c7f#q0",level:7,topics:["card:c7f","ch:c7","who:bo"],key:"c7f#0",title:"The doubling trick",play:{q:"Money grows 8 in every 100 each year. Roughly how long until it doubles?",opts:["About 9 years","About 80 years","About 72 years","About 8 years"],after:"72 ÷ 8 = 9. Bigger growth, faster doubling — and it is only ever a rough guide."},route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-q0",bands:["sprout","builder"]},"f-card-c7f-q1":{kind:"question",src:"card:c7f#q1",level:7,topics:["card:c7f","ch:c7","who:bo"],key:"c7f#1",title:"The doubling trick",play:{q:"Money grows 12 in every 100 each year. About how long to double?",opts:["About 6 years","About 60 years","About 24 years","About 12 years"],after:"72 ÷ 12 = 6. Faster growth halves the wait."},route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-q1",bands:["sprout","builder"]},"f-card-c7f-q2":{kind:"question",src:"card:c7f#q2",level:7,topics:["card:c7f","ch:c7","who:bo"],key:"c7f#2",title:"The doubling trick",play:{q:"What is the doubling trick good for?",opts:["A quick rough guess","An exact promise","Knowing next week's price","Picking which company to buy"],after:"It is a rule of thumb — quick and rough, never a promise about any real investment."},route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-q2",bands:["sprout","builder"]},"f-card-c7f-why0":{kind:"why",src:"card:c7f#why0",level:7,topics:["card:c7f","ch:c7","who:bo"],card:"c7f",title:"The doubling trick",body:"72 ÷ 8 = 9. Bigger growth, faster doubling — and it is only ever a rough guide.",route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-why0",bands:["sprout","builder"]},"f-card-c7f-why1":{kind:"why",src:"card:c7f#why1",level:7,topics:["card:c7f","ch:c7","who:bo"],card:"c7f",title:"The doubling trick",body:"72 ÷ 12 = 6. Faster growth halves the wait.",route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-why1",bands:["sprout","builder"]},"f-card-c7f-why2":{kind:"why",src:"card:c7f#why2",level:7,topics:["card:c7f","ch:c7","who:bo"],card:"c7f",title:"The doubling trick",body:"It is a rule of thumb — quick and rough, never a promise about any real investment.",route:"#/atlas/c7f",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Bo",id:"f-card-c7f-why2",bands:["sprout","builder"]},"f-tryit-c7f":{kind:"tryit",src:"tryit:c7f",level:7,topics:["card:c7f","ch:c7","who:bo"],title:"Try it",body:"The doubling trick",route:"#/atlas/c7f",cta:"Change the numbers",maths:"M12",source:"Chapter 7 · Money that grows · The doubling trick · with Bo",id:"f-tryit-c7f",bands:["sprout","builder"]},"f-card-c7g-teach":{kind:"lesson",src:"card:c7g#teach",level:7,topics:["card:c7g","ch:c7","who:nana"],title:"Staying in",body:"Jumping out when prices fall and back in when they rise sounds clever. Nobody can do it reliably. Staying in through the bad weeks usually beats guessing.",route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",card:"c7g",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-teach",bands:["sprout","builder"]},"f-card-c7g-eg":{kind:"example",src:"card:c7g#eg",level:7,topics:["card:c7g","ch:c7","who:nana"],title:"Staying in",body:"Bo sold on a red day and missed the bounce the week after. Bea did nothing and was fine.",route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-eg",bands:["sprout","builder"]},"f-card-c7g-q0":{kind:"question",src:"card:c7g#q0",level:7,topics:["card:c7g","ch:c7","who:nana"],key:"c7g#0",title:"Staying in",play:{q:"The Exchange fell all week. What usually works out better for money you will not need for years?",opts:["Leave it where it is","Sell now and buy back when it feels safe","Move it all into one company","Sell half, then decide each morning"],after:"Guessing the bottom twice — when to leave and when to return — is how people lose the bounce."},route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-q0",bands:["sprout","builder"]},"f-card-c7g-q1":{kind:"question",src:"card:c7g#q1",level:7,topics:["card:c7g","ch:c7","who:nana"],key:"c7g#1",title:"Staying in",play:{q:"Why is it so hard to jump out of the Exchange and back in at the right moments?",opts:["You have to guess right twice","Prices never change","The bank stops you","Selling is not allowed"],after:"Leaving early and returning late both cost you — and nobody knows the turning points in advance."},route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-q1",bands:["sprout","builder"]},"f-card-c7g-q2":{kind:"question",src:"card:c7g#q2",level:7,topics:["card:c7g","ch:c7","who:nana"],key:"c7g#2",title:"Staying in",play:{q:"Which player usually does best over many seasons in the Market Cup?",opts:["The calm one who spreads money out and waits","The one who sells every red day","The one who buys whatever rose most","The one who copies Bo"],after:"Spread out, sit still, give it time. Boring is the winning move."},route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-q2",bands:["sprout","builder"]},"f-card-c7g-why0":{kind:"why",src:"card:c7g#why0",level:7,topics:["card:c7g","ch:c7","who:nana"],card:"c7g",title:"Staying in",body:"Guessing the bottom twice — when to leave and when to return — is how people lose the bounce.",route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-why0",bands:["sprout","builder"]},"f-card-c7g-why1":{kind:"why",src:"card:c7g#why1",level:7,topics:["card:c7g","ch:c7","who:nana"],card:"c7g",title:"Staying in",body:"Leaving early and returning late both cost you — and nobody knows the turning points in advance.",route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-why1",bands:["sprout","builder"]},"f-card-c7g-why2":{kind:"why",src:"card:c7g#why2",level:7,topics:["card:c7g","ch:c7","who:nana"],card:"c7g",title:"Staying in",body:"Spread out, sit still, give it time. Boring is the winning move.",route:"#/atlas/c7g",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Nana Bizz",id:"f-card-c7g-why2",bands:["sprout","builder"]},"f-item-c7g":{kind:"yourturn",src:"item:c7g",level:7,topics:["card:c7g","ch:c7","who:nana"],title:"Your turn",body:`Staying in, or guessing?
Guessing means being right twice: when to leave and when to come back.`,route:"#/atlas/c7g",cta:"Have a go",maths:"M12",source:"Chapter 7 · Money that grows · Staying in · with Nana Bizz",id:"f-item-c7g",bands:["sprout","builder"]},"f-card-c7h-teach":{kind:"lesson",src:"card:c7h#teach",level:7,topics:["card:c7h","ch:c7","who:pip"],title:"Prices creep up",body:"Most years, prices creep up a little. Money left in a tin keeps its number but buys a bit less. To really grow, money has to grow faster than prices.",route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",card:"c7h",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-teach",bands:["sprout","builder"]},"f-card-c7h-eg":{kind:"example",src:"card:c7h#eg",level:7,topics:["card:c7h","ch:c7","who:pip"],title:"Prices creep up",body:"A snack that costs 10 now might cost 11 in a few years. The 10 in your tin did not change — what it buys did.",route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-eg",bands:["sprout","builder"]},"f-card-c7h-q0":{kind:"question",src:"card:c7h#q0",level:7,topics:["card:c7h","ch:c7","who:pip"],key:"c7h#0",title:"Prices creep up",play:{q:"Your tin holds the same money for five years while prices creep up. What happened?",opts:["It buys a little less","It grew by itself","It buys exactly what it did","It buys more, because it waited"],after:"Same number, smaller shopping bag. That is what rising prices do to money that sits still."},route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-q0",bands:["sprout","builder"]},"f-card-c7h-q1":{kind:"question",src:"card:c7h#q1",level:7,topics:["card:c7h","ch:c7","who:pip"],key:"c7h#1",title:"Money that grows",play:{q:"Why might money in a tin buy less in ten years?",opts:["Prices usually creep up","Coins get lighter","Tins leak","Shops lose count"],after:"The money keeps its number; the prices around it move."},route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-q1",bands:["sprout","builder"]},"f-card-c7h-q2":{kind:"question",src:"card:c7h#q2",level:7,topics:["card:c7h","ch:c7","who:pip"],key:"c7h#2",title:"Money that grows",play:{q:"For money to really grow, what must it beat?",opts:["The rise in prices","Last week's weather","Your friend's savings","The number on the note"],after:"Growth that is slower than rising prices is shrinking in disguise."},route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-q2",bands:["sprout","builder"]},"f-card-c7h-why0":{kind:"why",src:"card:c7h#why0",level:7,topics:["card:c7h","ch:c7","who:pip"],card:"c7h",title:"Prices creep up",body:"Same number, smaller shopping bag. That is what rising prices do to money that sits still.",route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-why0",bands:["sprout","builder"]},"f-card-c7h-why1":{kind:"why",src:"card:c7h#why1",level:7,topics:["card:c7h","ch:c7","who:pip"],card:"c7h",title:"Prices creep up",body:"The money keeps its number; the prices around it move.",route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-why1",bands:["sprout","builder"]},"f-card-c7h-why2":{kind:"why",src:"card:c7h#why2",level:7,topics:["card:c7h","ch:c7","who:pip"],card:"c7h",title:"Prices creep up",body:"Growth that is slower than rising prices is shrinking in disguise.",route:"#/atlas/c7h",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · with Pip",id:"f-card-c7h-why2",bands:["sprout","builder"]},"f-chapter-c7":{kind:"chapter",src:"chapter:c7",level:7,topics:["ch:c7"],title:"Money that grows",body:"Compounding, risk, and why nobody sensible owns just one thing.",route:"#/atlas/chapter/c7",cta:"The Money Atlas",maths:"M12",source:"Chapter 7 of 8 · 10 lessons on the Money Atlas",id:"f-chapter-c7",bands:["sprout","builder"]},"f-goal-grow-3":{kind:"goal",src:"goal:GROW-3",level:7,topics:["card:c7a","ch:c7"],title:"Why the second time is bigger",body:"Explains why the second period earns more than the first without anything new being added.",route:"#/atlas/c7a",cta:"Open the lesson",maths:"M11",source:"Chapter 7 · Money that grows · what the lesson is for",id:"f-goal-grow-3",bands:["sprout","builder"]},"f-goal-grow-4":{kind:"goal",src:"goal:GROW-4",level:7,topics:["card:c7b","ch:c7"],title:"What the extra costs",body:"Given two possible returns, says which is higher and names what is being risked to get it.",route:"#/atlas/c7b",cta:"Open the lesson",maths:"M10",source:"Chapter 7 · Money that grows · what the lesson is for",id:"f-goal-grow-4",bands:["sprout","builder"]},"f-goal-grow-5":{kind:"goal",src:"goal:GROW-5",level:7,topics:["card:c7c","ch:c7"],title:"Never just one",body:"Spreads money across more than one holding and can say what that protects them from.",route:"#/atlas/c7c",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · what the lesson is for",id:"f-goal-grow-5",bands:["sprout","builder"]},"f-goal-grow-6":{kind:"goal",src:"goal:GROW-6",level:7,topics:["card:c7d","ch:c7"],title:"Doing nothing on purpose",body:"Does nothing on a day everything falls, and can say afterwards that doing nothing was the decision.",route:"#/atlas/c7d",cta:"Open the lesson",maths:"M6",source:"Chapter 7 · Money that grows · what the lesson is for",id:"f-goal-grow-6",bands:["sprout","builder"]},"f-goal-grow-7":{kind:"goal",src:"goal:GROW-7",level:7,topics:["card:c7d","ch:c7"],title:"Time is the ingredient",body:"Says what years do to a small regular amount, and that starting earlier beats adding more later.",route:"#/atlas/c7d",cta:"Open the lesson",maths:"M12",source:"Chapter 7 · Money that grows · what the lesson is for",id:"f-goal-grow-7",bands:["sprout","builder"]},"f-goal-grow-8":{kind:"goal",src:"goal:GROW-8",level:7,topics:["card:c7b","ch:c7"],title:"Money you can leave alone",body:"Separates money they can leave alone for years from money they need soon, and puts each somewhere different.",route:"#/atlas/c7b",cta:"Open the lesson",maths:"M8",source:"Chapter 7 · Money that grows · what the lesson is for",id:"f-goal-grow-8",bands:["sprout","builder"]},"f-word-compounding":{kind:"word",src:"word:Compounding",level:7,topics:["word","word:Compounding","ch:c7"],title:"Compounding",body:"Growth landing on earlier growth.",route:"#/words/Compounding",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-compounding",bands:["sprout","builder"],maths:"M11"},"f-word-compounding-more":{kind:"wordmore",src:"word:Compounding#more",level:7,topics:["word","word:Compounding","ch:c7"],title:"Compounding",body:"Boring for a year, then not boring at all. Time does the work.",route:"#/words/Compounding",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-compounding-more",bands:["sprout","builder"],maths:"M11"},"f-word-return":{kind:"word",src:"word:Return",level:7,topics:["word","word:Return","ch:c7"],title:"Return",body:"What you got back, over what you put in.",route:"#/words/Return",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-return",bands:["sprout","builder"],maths:"M1"},"f-word-return-more":{kind:"wordmore",src:"word:Return#more",level:7,topics:["word","word:Return","ch:c7"],title:"Return",body:"Usually a percentage, usually quoted by someone who wants something.",route:"#/words/Return",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-return-more",bands:["sprout","builder"],maths:"M10"},"f-word-fund":{kind:"word",src:"word:Fund",level:7,topics:["word","word:Fund","ch:c7"],title:"Fund",body:"A basket holding many things at once.",route:"#/words/Fund",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-fund",bands:["sprout","builder"],maths:"M1"},"f-word-fund-more":{kind:"wordmore",src:"word:Fund#more",level:7,topics:["word","word:Fund","ch:c7"],title:"Fund",body:"One purchase, lots of eggs, lots of baskets.",route:"#/words/Fund",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-fund-more",bands:["sprout","builder"],maths:"M1"},"f-word-profit":{kind:"word",src:"word:Profit",level:7,topics:["word","word:Profit","ch:c7"],title:"Profit",body:"Revenue minus cost.",route:"#/words/Profit",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-profit",bands:["sprout","builder"],maths:"M1"},"f-word-profit-more":{kind:"wordmore",src:"word:Profit#more",level:7,topics:["word","word:Profit","ch:c7"],title:"Profit",body:"The number that decides whether you are still open next year.",route:"#/words/Profit",cta:"Money Words",source:"Money Words · first used in Chapter 7 · Money that grows",id:"f-word-profit-more",bands:["sprout","builder"],maths:"M1"},"f-figure-grow":{kind:"figure",src:"figure:grow",level:7,topics:["figure","ch:c7"],badge:{id:"own",label:"A dial of this town"},title:"The Grow jar's long-run rate",body:`7% a year
A dial of this town, chosen so that compounding is visible inside a childhood rather than to match anything real. It is not a forecast, it is not any market's record, and no real investment is being described.`,route:"#/sources/grow",cta:"How we know",source:"How we know",id:"f-figure-grow",bands:["sprout","builder"],maths:"M10"},"f-figure-inflation":{kind:"figure",src:"figure:inflation",level:7,topics:["figure","ch:c7"],badge:{id:"own",label:"A dial of this town"},title:"Why prices drift up",body:`the town aims at 3%
The town has a target and misses it, the way a real one does. The shape is honest; the numbers are the town's.`,route:"#/sources/inflation",cta:"How we know",source:"How we know",id:"f-figure-inflation",bands:["sprout","builder"],maths:"M10"},"f-figure-market":{kind:"figure",src:"figure:market",level:7,topics:["figure","ch:c7"],badge:{id:"own",label:"A dial of this town"},title:"The companies on the Exchange",body:`four, none of them real
Fictional names, moving on the town's own generated series. No real company is named anywhere with a buy button, and nothing here is investment advice.`,route:"#/sources/market",cta:"How we know",source:"How we know",id:"f-figure-market",bands:["sprout","builder"],maths:"M1"},"f-game-st":{kind:"game",src:"game:st",level:7,topics:["game","game:st","ch:c7"],gate:{chapter:"c7"},title:"Market Storm",body:`Everything is red and everyone is shouting sell. The winning move is to do nothing, and it is much harder than it sounds.
doing nothing on a red day`,route:"#/play/st",cta:"Go and play",source:"Play · keys space · opens with Chapter 7 · Money that grows",id:"f-game-st",bands:["sprout","builder"],maths:"M1"},"f-game-mc":{kind:"game",src:"game:mc",level:7,topics:["game","game:mc","ch:c7"],gate:{chapter:"c7"},title:"The Market Cup",body:`Six weeks against Chaser, Panicker and Boring Bella. Bella is annoying.
spreading money out and keeping your nerve`,route:"#/play/mc",cta:"Go and play",source:"Play · keys ↑↓←→ ⏎ · opens with Chapter 7 · Money that grows",id:"f-game-mc",bands:["sprout","builder"],maths:"M1"},"f-quest-q-invest":{kind:"quest",src:"quest:q-invest",level:7,topics:["quest","ch:c7"],gate:{chapter:"c7"},title:"Add to your holdings",body:"From the Grow jar, as always.",route:"#/town/today",cta:"Today's three",source:"Today's three · on the town page",id:"f-quest-q-invest",bands:["sprout","builder"],maths:"M1"},"f-badge-chapter-c7":{kind:"medal",src:"badge:chapter-c7",level:7,topics:["medal","ch:c7"],badgeId:"chapter-c7",title:"Money that grows",body:"Chapter seven, done.",route:"#/medals/chapter-c7",cta:"How to earn it",source:"Medal · for finishing Chapter 7 · Money that grows",id:"f-badge-chapter-c7",bands:["sprout","builder"],maths:"M1"},"f-asset-basket":{kind:"exchange",src:"asset:basket",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},title:"Whole Market Basket",body:"A slice of every shop in town. Dull by design.",route:"#/money/portfolio/basket",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-asset-basket",bands:["sprout","builder"],maths:"M1"},"f-asset-grain":{kind:"exchange",src:"asset:grain",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},title:"Sunrise Grains",body:"People eat in good years and bad. Rarely exciting.",route:"#/money/portfolio/grain",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-asset-grain",bands:["sprout","builder"],maths:"M1"},"f-asset-chai":{kind:"exchange",src:"asset:chai",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},title:"Chai Chain Co",body:"Opening shops fast. Fast can go both ways.",route:"#/money/portfolio/chai",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-asset-chai",bands:["sprout","builder"],maths:"M1"},"f-asset-rocket":{kind:"exchange",src:"asset:rocket",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},title:"Rocket Rickshaws",body:"Might be the future. Might be a rickshaw.",route:"#/money/portfolio/rocket",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-asset-rocket",bands:["sprout","builder"],maths:"M1"},"f-class-cash":{kind:"exchange",src:"class:cash",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},bands:["sprout","builder"],maths:"M1",title:"Cash",body:`Safe, and it does nothing.
It never falls in number — and prices climb underneath it.`,route:"#/money/portfolio/cash",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-class-cash"},"f-class-deposit":{kind:"exchange",src:"class:deposit",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},bands:["sprout","builder"],maths:"M4",title:"The deposit",body:`The bank pays you to leave it there.
Follows the bank rate, a little below it. The bank keeps the difference.`,route:"#/money/portfolio/deposit",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-class-deposit"},"f-class-bond":{kind:"exchange",src:"class:bond",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},bands:["builder"],maths:"M10",title:"A loan you made",body:`You are the lender. Somebody pays you a coupon.
When new loans pay more, yours is worth less — so the price falls when the rate rises.`,route:"#/money/portfolio/bond",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-class-bond"},"f-class-shares":{kind:"exchange",src:"class:shares",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},bands:["builder"],maths:"M12",title:"One company",body:`A piece of a business that earns.
Falls when the town slows AND when the rate rises. Two reasons, and they can arrive together.`,route:"#/money/portfolio/shares",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-class-shares"},"f-class-gold":{kind:"exchange",src:"class:gold",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},bands:["builder"],maths:"M13",title:"Gold",body:`It pays you nothing at all.
People want it when money is losing value — so it often rises when shares do not.`,route:"#/money/portfolio/gold",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-class-gold"},"f-class-property":{kind:"exchange",src:"class:property",level:7,topics:["ch:c7","exchange"],gate:{chapter:"c7"},bands:["builder"],maths:"M13",title:"A house to let",body:`Rent comes in. You cannot sell half of it.
Tracks prices and the town, pays rent, and costs a fortune to buy and sell.`,route:"#/money/portfolio/property",cta:"The Exchange",source:"The Exchange · Chapter 7 · Money that grows",id:"f-class-property"}};export{e as default};
